<?php $seasonDoc=localized_season($titleItem,$sn);$seasonImages=(array)($seasonDoc['episodes']??[]); ?>
<div class="episode-grid"><?php foreach($seasonEpisodes as $ep):$en=(int)($ep['episode']??1);$extra=$seasonImages[$en]??[];foreach(['title','description','air_date','image'] as $key)if(!empty($extra[$key])&&($key==='title'||$key==='description'||empty($ep[$key])))$ep[$key]=$extra[$key];$epTitle=episode_title($ep);$epImage=valid_image_url($ep['image']??'')?$ep['image']:media_url($titleItem,'episode',$sn,$en);?>
<article class="episode" data-episode-key="<?=e($titleItem['imdb_id'].':'.$sn.':'.$en)?>"><button class="episode-media js-play" type="button" data-player="<?=e(player_url($titleItem,$sn,$en))?>" data-title="<?=e(title_name($titleItem).' · S'.$sn.' · E'.$en)?>" data-id="<?=e($titleItem['imdb_id'])?>" data-season="<?=$sn?>" data-episode="<?=$en?>" aria-label="Redă episodul <?=$en?>: <?=e($epTitle)?>"><img referrerpolicy="no-referrer" src="<?=e($epImage)?>" alt="" width="500" height="281" loading="lazy" decoding="async" data-fallback="/assets/img/episode-placeholder.svg"><span class="episode-play"><?=icon('play')?></span><span class="episode-index">S<?=$sn?> · E<?=$en?></span></button><div class="episode-content"><p class="episode-top"><span>Episodul <?=$en?></span><?php if(!empty($ep['runtime'])):?><span><?=e(compact_duration($ep['runtime']))?></span><?php endif;?><?php if(!empty($ep['rating'])):?><span>IMDb ★ <?=e(number_format((float)$ep['rating'],1,',',''))?></span><?php endif;?></p><h3 class="episode-title"><?=e($epTitle)?></h3><?php if(!empty($ep['air_date'])&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$ep['air_date'])):?><p class="episode-date">Difuzat: <?=e(implode('.',array_reverse(explode('-',$ep['air_date']))))?></p><?php endif;?><?php if(!empty($ep['description'])):?><p class="episode-description"><?=e($ep['description'])?></p><?php endif;?><div class="episode-progress" hidden><progress max="100" value="0" aria-label="Progres episod"></progress><small></small></div><button class="text-btn js-play" type="button" data-player="<?=e(player_url($titleItem,$sn,$en))?>" data-title="<?=e(title_name($titleItem).' · S'.$sn.' · E'.$en)?>" data-id="<?=e($titleItem['imdb_id'])?>" data-season="<?=$sn?>" data-episode="<?=$en?>"><?=icon('play')?> <span data-episode-label>Redă episodul</span></button></div></article>
<?php endforeach;?></div>
